 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    blocks = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[y][x] == 2 for y, x in ((r,c),(r+1,c),(r,c+1),(r+1,c+1))):
                blocks.append((r,c))
    for r, c in blocks:
        points = ((r-1,c-1), (r-1,c+2), (r+2,c+2), (r+2,c-1))  # TL, TR, BR, BL
        if not all(0 <= y < h and 0 <= x < w for y,x in points):
            continue
        colors = [grid[y][x] for y,x in points]
        # Move each corner's color one position clockwise in the TL,TR,BR,BL ordering.
        moved = [colors[3], colors[0], colors[1], colors[2]]
        directions = ((-1,-1), (-1,1), (1,1), (1,-1))
        for (y,x), color, (dy,dx) in zip(points, moved, directions):
            yy, xx = y, x
            while 0 <= yy < h and 0 <= xx < w:
                out[yy][xx] = color
                yy += dy
                xx += dx
    return out
